package unit

import (
	"path/filepath"
	"testing"

	"github.com/gruntwork-io/terratest/modules/terraform"
	"github.com/stretchr/testify/assert"
)

func TestServiceName(t *testing.T) {
	t.Parallel()

	options := terraform.WithDefaultRetryableErrors(t, &terraform.Options{
		TerraformDir: "../..",
		PlanFilePath: filepath.Join(t.TempDir(), "plan.tfplan"),
		Vars: map[string]interface{}{
			"name": "api",
			"host": "api.example.internal",
		},
	})

	plan := terraform.InitAndPlanAndShowWithStruct(t, options)
	output := plan.RawPlan.PlannedValues.Outputs["service_name"]

	assert.Equal(t, "svc-api", output.Value)
}
//go:build integration

package integration

import (
	"testing"

	"github.com/gruntwork-io/terratest/modules/terraform"
	"github.com/stretchr/testify/assert"
)

func TestApplyRecordsService(t *testing.T) {
	options := terraform.WithDefaultRetryableErrors(t, &terraform.Options{
		TerraformDir: "../..",
		Vars: map[string]interface{}{
			"name": "api",
			"host": "api.example.internal",
		},
	})

	defer terraform.Destroy(t, options)
	terraform.InitAndApply(t, options)

	assert.Equal(t, "svc-api", terraform.Output(t, options, "service_name"))
}
resource "terraform_data" "service" {
  input = {
    name = var.name
    host = var.host
    port = var.port
  }
}
terraform {
  required_version = ">= 1.3.0"
}
# service-endpoint

A module that records one service and the address clients use to reach it.

## Tests

The tests are Terratest tests under `test/`, with their own `go.mod`. Run them from that directory.

- `test/unit/` holds one file per output, named for it, and every test plans and reads the planned
  values without applying. `go test ./unit/...` runs them.
- `test/integration/` holds tests that apply. They carry the `integration` build tag and CI runs
  them in a sandbox account, so nobody adds to them without the platform team.

