cat > test/unit/endpoint_test.go <<'EOF'
package unit

import (
	"path/filepath"
	"testing"

	"github.com/gruntwork-io/terratest/modules/terraform"
	"github.com/stretchr/testify/assert"
)

func TestEndpoint(t *testing.T) {
	t.Parallel()

	cases := map[string]struct {
		vars     map[string]interface{}
		expected string
	}{
		"default port": {
			vars:     map[string]interface{}{"name": "api", "host": "api.example.internal"},
			expected: "https://api.example.internal:8443",
		},
		"explicit port": {
			vars:     map[string]interface{}{"name": "api", "host": "api.example.internal", "port": 9000},
			expected: "https://api.example.internal:9000",
		},
	}

	for name, tc := range cases {
		tc := tc
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			options := terraform.WithDefaultRetryableErrors(t, &terraform.Options{
				TerraformDir: "../..",
				PlanFilePath: filepath.Join(t.TempDir(), "plan.tfplan"),
				Vars:         tc.vars,
			})

			plan := terraform.InitAndPlanAndShowWithStruct(t, options)
			output := plan.RawPlan.PlannedValues.Outputs["endpoint"]

			assert.Equal(t, tc.expected, output.Value)
		})
	}
}
EOF
cd test && timeout 300 go test ./unit/... 2>&1 | tail -15

